/** static u16 PartyMenuButtonHandler(s8 *slotPtr) */
export function PartyMenuButtonHandler(slotPtr: any): any {
  let movementDir: any = null;

      switch (gMain.newAndRepeatedKeys)
      {
      case DPAD_UP:
          movementDir = (-1);
          break;
      case DPAD_DOWN:
          movementDir = (1);
          break;
      case DPAD_LEFT:
          movementDir = (-2);
          break;
      case DPAD_RIGHT:
          movementDir = (2);
          break;
      default:
          switch (GetLRKeysPressedAndHeld())
          {
          case (1):
              movementDir = (-1);
              break;
          case (2):
              movementDir = (1);
              break;
          default:
              movementDir = 0;
              break;
          }
          break;
      }

      if (JOY_NEW(START_BUTTON))
          return START_BUTTON;

      if (movementDir)
      {
          UpdateCurrentPartySelection(slotPtr, movementDir);
          return 0;
      }

       
      if (JOY_NEW(A_BUTTON) && slotPtr == (6) + 1)
          return B_BUTTON;

      return JOY_NEW(A_BUTTON | B_BUTTON);
}

/** static void UpdateCurrentPartySelection(s8 *slotPtr, s8 movementDir) */
export function UpdateCurrentPartySelection(slotPtr: any, movementDir: any): any {
  let newSlotId: any = slotPtr;
      let layout: any = gPartyMenu.layout;

      if (layout == (0))
          UpdatePartySelectionSingleLayout(slotPtr, movementDir);
      else
          UpdatePartySelectionDoubleLayout(slotPtr, movementDir);

      if (slotPtr != newSlotId)
      {
          PlaySE((5));
          AnimatePartySlot(newSlotId, 0);
          AnimatePartySlot(slotPtr, 1);
      }
}

/** static void UpdatePartySelectionSingleLayout(s8 *slotPtr, s8 movementDir) */
export function UpdatePartySelectionSingleLayout(slotPtr: any, movementDir: any): any {
  switch (movementDir)
      {
      case (-1):
          if (slotPtr == 0)
          {
              slotPtr = (6) + 1;
          }
          else if (slotPtr == (6))
          {
              slotPtr = gPlayerPartyCount - 1;
          }
          else if (slotPtr == (6) + 1)
          {
              if (sPartyMenuInternal.chooseHalf)
                  slotPtr = (6);
              else
                  slotPtr = gPlayerPartyCount - 1;
          }
          else
          {
              slotPtr--;
          }
          break;
      case (1):
          if (slotPtr == (6) + 1)
          {
              slotPtr = 0;
          }
          else
          {
              if (slotPtr == gPlayerPartyCount - 1)
              {
                  if (sPartyMenuInternal.chooseHalf)
                      slotPtr = (6);
                  else
                      slotPtr = (6) + 1;
              }
              else
              {
                  slotPtr++;
              }
          }
          break;
      case (2):
          if (gPlayerPartyCount != 1 && slotPtr == 0)
          {
              if (sPartyMenuInternal.lastSelectedSlot == 0)
                  slotPtr = 1;
              else
                  slotPtr = sPartyMenuInternal.lastSelectedSlot;
          }
          break;
      case (-2):
          if (slotPtr != 0 && slotPtr != (6) && slotPtr != (6) + 1)
          {
              sPartyMenuInternal.lastSelectedSlot = slotPtr;
              slotPtr = 0;
          }
          break;
      }
}

/** static void UpdatePartySelectionDoubleLayout(s8 *slotPtr, s8 movementDir) */
export function UpdatePartySelectionDoubleLayout(slotPtr: any, movementDir: any): any {
  let newSlot: any = movementDir;

      switch (movementDir)
      {
      case (-1):
          if (slotPtr == 0)
          {
              slotPtr = (6) + 1;
              break;
          }
          else if (slotPtr == (6))
          {
              slotPtr = gPlayerPartyCount - 1;
              break;
          }
          else if (slotPtr == (6) + 1)
          {
              if (sPartyMenuInternal.chooseHalf)
              {
                  slotPtr = (6);
                  break;
              }
              slotPtr--;
          }
          newSlot = GetNewSlotDoubleLayout(slotPtr, newSlot);
          if (newSlot != -1)
              slotPtr = newSlot;
          break;
      case (1):
          if (slotPtr == (6))
          {
              slotPtr = (6) + 1;
          }
          else if (slotPtr == (6) + 1)
          {
              slotPtr = 0;
          }
          else
          {
              newSlot = GetNewSlotDoubleLayout(slotPtr, (1));
              if (newSlot == -1)
              {
                  if (sPartyMenuInternal.chooseHalf)
                      slotPtr = (6);
                  else
                      slotPtr = (6) + 1;
              }
              else
              {
                  slotPtr = newSlot;
              }
          }
          break;
      case (2):
          if (slotPtr == 0)
          {
              if (sPartyMenuInternal.lastSelectedSlot == 3)
              {
                  if (GetMonData(gPlayerParty[3], MON_DATA_SPECIES) != (0))
                      slotPtr = 3;
              }
              else if (GetMonData(gPlayerParty[2], MON_DATA_SPECIES) != (0))
              {
                  slotPtr = 2;
              }
          }
          else if (slotPtr == 1)
          {
              if (sPartyMenuInternal.lastSelectedSlot == 5)
              {
                  if (GetMonData(gPlayerParty[5], MON_DATA_SPECIES) != (0))
                      slotPtr = 5;
              }
              else if (GetMonData(gPlayerParty[4], MON_DATA_SPECIES) != (0))
              {
                  slotPtr = 4;
              }
          }
          break;
      case (-2):
          if (slotPtr == 2 || slotPtr == 3)
          {
              sPartyMenuInternal.lastSelectedSlot = slotPtr;
              slotPtr = 0;
          }
          else if (slotPtr == 4 || slotPtr == 5)
          {
              sPartyMenuInternal.lastSelectedSlot = slotPtr;
              slotPtr = 1;
          }
          break;
      }
}

/** static s8 GetNewSlotDoubleLayout(s8 slotId, s8 movementDir) */
export function GetNewSlotDoubleLayout(slotId: any, movementDir: any): any {
  while (TRUE)
      {
          slotId += movementDir;
          if (slotId >= (6))
              return -1;
          if (GetMonData(gPlayerParty[slotId], MON_DATA_SPECIES) != (0))
              return slotId;
      }
}

