/** u8 GetAilmentFromStatus(u32 status) */
export function GetAilmentFromStatus(status: any): any {
  if (status & ((((1 << 3)) | ((1 << 7)))))
          return (1);
      if (status & ((1 << 6)))
          return (2);
      if (status & ((1 << 0 | 1 << 1 | 1 << 2)))
          return (3);
      if (status & ((1 << 5)))
          return (4);
      if (status & ((1 << 4)))
          return (5);
      return (0);
}

/** u8 GetMonAilment(struct Pokemon *mon) */
export function GetMonAilment(mon: any): any {
  let ailment: any = null;

      if (GetMonData(mon, MON_DATA_HP) == 0)
          return (7);
      ailment = GetAilmentFromStatus(GetMonData(mon, MON_DATA_STATUS));
      if (ailment != (0))
          return ailment;
      if (CheckPartyPokerus(mon, 0))
          return (6);
      return (0);
}

/** static void SetPartyMonsAllowedInMinigame(void) */
export function SetPartyMonsAllowedInMinigame(): any {
  let ptr: any = null;

      if (gPartyMenu.menuType == (11))
      {
          let i: any = null;

          ptr =gPartyMenu.data1;
          gPartyMenu.data1 = 0;
          if (gSpecialVar_0x8005 == 0)
          {
              for (i = 0; i < gPlayerPartyCount; i++)
                  ptr += IsMonAllowedInPokemonJump(gPlayerParty[i]) << i;
          }
          else
          {
              for (i = 0; i < gPlayerPartyCount; i++)
                  ptr += IsMonAllowedInDodrioBerryPicking(gPlayerParty[i]) << i;
          }
      }
}

