              DisplayPartyPokemonDescriptionText(i + (2),sPartyMenuBoxes[gPartyMenu.slotId], 1);
              if (i == (maxBattlers - 1))
                  MoveCursorToConfirm();
              DisplayPartyMenuStdMessage((0));
              gTasks[taskId].func = Task_HandleChooseMonInput;
              return;
