/** void CB2_ShowPartyMenuForItemUse(void) */
export function CB2_ShowPartyMenuForItemUse(): any {
  let callback: any = CB2_ReturnToBagMenu;
      let partyLayout: any = null;
      let menuType: any = null;
      let i: any = null;
      let msgId: any = null;
      let task: any = null;

      if (gMain.inBattle)
      {
          menuType = (1);
          partyLayout = GetPartyLayoutFromBattleType();
      }
      else
      {
          menuType = (0);
          partyLayout = (0);
      }

      if (GetItemEffectType(gSpecialVar_ItemId) == (10))
      {
          gPartyMenu.slotId = 0;
          for (i = 0; i < (6); i++)
          {
              if (GetMonData(gPlayerParty[i], MON_DATA_SPECIES) != (0) && GetMonData(gPlayerParty[i], MON_DATA_HP) == 0)
              {
                  gPartyMenu.slotId = i;
                  break;
              }
          }
          task = Task_SetSacredAshCB;
          msgId = (127);
      }
      else
      {
          if (GetPocketByItemId(gSpecialVar_ItemId) == (3))
              msgId = (4);
          else
              msgId = (5);

          task = Task_HandleChooseMonInput;
      }

      InitPartyMenu(menuType, partyLayout, (3), TRUE, msgId, task, callback);
}

