/** static bool8 GetBattleEntryEligibility(struct Pokemon *mon) */
export function GetBattleEntryEligibility(mon: any): any {
  let i: any = 0;
      let species: any = null;

      if (GetMonData(mon, MON_DATA_IS_EGG)
          || GetMonData(mon, MON_DATA_LEVEL) > GetBattleEntryLevelCap()
          || (gSaveBlock1Ptr.location.mapGroup == MAP_GROUP(MAP_BATTLE_FRONTIER_BATTLE_PYRAMID_LOBBY)
              && gSaveBlock1Ptr.location.mapNum == MAP_NUM(MAP_BATTLE_FRONTIER_BATTLE_PYRAMID_LOBBY)
              && GetMonData(mon, MON_DATA_HELD_ITEM) != (0)))
      {
          return FALSE;
      }

      switch (VarGet((0x40CF)))
      {
      case (9):
          if (GetMonData(mon, MON_DATA_HP) != 0)
              return TRUE;
          return FALSE;
      case (8):
          return TRUE;
      default:  
          species = GetMonData(mon, MON_DATA_SPECIES);
          for (; gFrontierBannedSpecies[i] != 0xFFFF; i++)
          {
              if (gFrontierBannedSpecies[i] == species)
                  return FALSE;
          }
          return TRUE;
      }
}

/** static u8 CheckBattleEntriesAndGetMessage(void) */
export function CheckBattleEntriesAndGetMessage(): any {
  let maxBattlers: any = null;
      let i, j;
      let facility: any = null;
      let party: any = gPlayerParty;
      let minBattlers: any = GetMinBattleEntries();
      let order: any = gSelectedOrderFromParty;

      if (order[minBattlers - 1] == 0)
      {
          if (minBattlers == 1)
              return (14);
          ConvertIntToDecimalStringN(gStringVar1, minBattlers, STR_CONV_MODE_LEFT_ALIGN, 1);
          return (17);
      }

      facility = VarGet((0x40CF));
      if (facility == (8) || facility == (9))
          return 0xFF;

      maxBattlers = GetMaxBattleEntries();
      for (i = 0; i < maxBattlers - 1; i++)
      {
          let species: any = GetMonData(party[order[i] - 1], MON_DATA_SPECIES);
          let item: any = GetMonData(party[order[i] - 1], MON_DATA_HELD_ITEM);
          for (j = i + 1; j < maxBattlers; j++)
          {
              if (species == GetMonData(party[order[j] - 1], MON_DATA_SPECIES))
                  return (18);
              if (item != (0) && item == GetMonData(party[order[j] - 1], MON_DATA_HELD_ITEM))
                  return (19);
          }
      }

      return 0xFF;
}

