/** static void ShiftMoveSlot(struct Pokemon *mon, u8 slotTo, u8 slotFrom) */
export function ShiftMoveSlot(mon: any, slotTo: any, slotFrom: any): any {
  let move1: any = GetMonData(mon, MON_DATA_MOVE1 + slotTo);
      let move0: any = GetMonData(mon, MON_DATA_MOVE1 + slotFrom);
      let pp1: any = GetMonData(mon, MON_DATA_PP1 + slotTo);
      let pp0: any = GetMonData(mon, MON_DATA_PP1 + slotFrom);
      let ppBonuses: any = GetMonData(mon, MON_DATA_PP_BONUSES);
      let ppBonusMask1: any = gPPUpGetMask[slotTo];
      let ppBonusMove1: any = (ppBonuses & ppBonusMask1) >> (slotTo * 2);
      let ppBonusMask2: any = gPPUpGetMask[slotFrom];
      let ppBonusMove2: any = (ppBonuses & ppBonusMask2) >> (slotFrom * 2);
      ppBonuses &= ~ppBonusMask1;
      ppBonuses &= ~ppBonusMask2;
      ppBonuses |= (ppBonusMove1 << (slotFrom * 2)) + (ppBonusMove2 << (slotTo * 2));
      SetMonData(mon, MON_DATA_MOVE1 + slotTo,move0);
      SetMonData(mon, MON_DATA_MOVE1 + slotFrom,move1);
      SetMonData(mon, MON_DATA_PP1 + slotTo,pp0);
      SetMonData(mon, MON_DATA_PP1 + slotFrom,pp1);
      SetMonData(mon, MON_DATA_PP_BONUSES,ppBonuses);
}

